:root {
  --bg:      #0d0d1a;
  --primary: #00e5ff;
  --accent:  #ff6b35;
  --text:    #e8e8f0;
  --dim:     #6a6a8a;
}

* { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }

html, body {
  width: 100%; height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: 'Segoe UI', Arial, sans-serif;
  touch-action: none;
  user-select: none;
}

/* ── Screens ── */
.screen {
  display: none;
  position: fixed;
  inset: 0;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.screen.active { display: flex; }

/* ── Screen content (menu / gameover) ── */
.screen-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 32px 24px;
  background: rgba(0,0,0,0.6);
  border: 1px solid var(--primary);
  border-radius: 16px;
  max-width: 340px;
  width: 90%;
}

.title {
  font-size: 2.6rem;
  font-weight: 900;
  letter-spacing: 4px;
  text-align: center;
  color: var(--primary);
  text-shadow: 0 0 20px var(--primary);
  line-height: 1.1;
}
.title span { color: var(--accent); text-shadow: 0 0 20px var(--accent); }

.subtitle { color: var(--dim); font-size: 1rem; }
.hint { color: var(--dim); font-size: 0.8rem; }
.newbest { color: gold; font-size: 1.2rem; font-weight: bold; }

/* ── Buttons ── */
.btn {
  padding: 14px 36px;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: 2px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  width: 100%;
  touch-action: manipulation;
}
.btn-primary {
  background: var(--primary);
  color: #000;
  box-shadow: 0 0 16px var(--primary);
}
.btn-primary:active { opacity: 0.8; }
.btn-secondary {
  background: transparent;
  color: var(--text);
  border: 1px solid var(--dim);
}
.btn-secondary:active { opacity: 0.7; }

/* ── Game screen layout ── */
#screen-game {
  flex-direction: column;
  justify-content: flex-start;
}

/* ── HUD ── */
#hud {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
  background: rgba(0,0,0,0.5);
  font-size: 0.95rem;
  flex-shrink: 0;
  z-index: 10;
  height: 44px;
}
#hud b { color: var(--primary); }

/* ── Canvas ── */
#game-canvas {
  display: block;
  flex: 1;
  width: 100%;
}

/* ── Controls ── */
#controls {
  width: 100%;
  display: flex;
  justify-content: space-around;
  align-items: center;
  padding: 10px 16px;
  background: rgba(0,0,0,0.5);
  flex-shrink: 0;
  height: 90px;
  z-index: 10;
}

.ctrl-btn {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  border: 2px solid var(--primary);
  background: rgba(0,229,255,0.12);
  color: var(--primary);
  font-size: 1.6rem;
  cursor: pointer;
  touch-action: manipulation;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ctrl-btn:active { background: rgba(0,229,255,0.3); }

.fire-btn {
  width: 80px;
  height: 80px;
  border-color: var(--accent);
  background: rgba(255,107,53,0.15);
  color: var(--accent);
  font-size: 1.8rem;
}
.fire-btn:active { background: rgba(255,107,53,0.35); }

/* ── ARCADE BLASTER – game.js ── */

// ── Canvas & Context ──────────────────────────────────────────────
const canvas = document.getElementById('game-canvas');
if (!canvas) throw new Error('No canvas found');
const ctx = canvas.getContext('2d');
if (!ctx) throw new Error('No 2d context');

// ── CSS Variables ─────────────────────────────────────────────────
const style = getComputedStyle(document.documentElement);
const C = {
  bg:      () => style.getPropertyValue('--bg').trim()      || '#0d0d1a',
  primary: () => style.getPropertyValue('--primary').trim() || '#00e5ff',
  accent:  () => style.getPropertyValue('--accent').trim()  || '#ff6b35',
  text:    () => style.getPropertyValue('--text').trim()    || '#e8e8f0',
  dim:     () => style.getPropertyValue('--dim').trim()     || '#6a6a8a',
};

// ── State ─────────────────────────────────────────────────────────
let gameState = 'menu'; // 'menu'|'playing'|'gameover'
let score = 0;
let bestScore = 0;
try { bestScore = parseInt(localStorage.getItem('arcade_best') || '0', 10) || 0; } catch(e) {}
let level = 1;
let lives = 3;
let frameCount = 0;

// ── Game Objects ──────────────────────────────────────────────────
let player = {};
let bullets = [];
let enemies = [];
let stars = [];
let particles = [];
let bgStars = [];

// ── Enemy spawn timer & auto-fire ─────────────────────────────────
let enemySpawnTimer = 0;
let autoFireTimer   = 0;

// ── Resize ────────────────────────────────────────────────────────
function resizeCanvas() {
  const hudEl      = document.getElementById('hud');
  const controlsEl = document.getElementById('controls');
  const hudH       = hudEl      ? hudEl.offsetHeight      : 44;
  const controlsH  = controlsEl ? controlsEl.offsetHeight : 90;

  canvas.width  = window.innerWidth;
  canvas.height = Math.max(100, window.innerHeight - hudH - controlsH);

  initBgStars();
  if (gameState !== 'playing') resetPlayer();
}
window.addEventListener('resize', resizeCanvas);

// ── Background Stars ──────────────────────────────────────────────
function initBgStars() {
  bgStars = [];
  const count = Math.floor((canvas.width * canvas.height) / 4000);
  for (let i = 0; i < count; i++) {
    bgStars.push({
      x:     Math.random() * canvas.width,
      y:     Math.random() * canvas.height,
      r:     Math.random() * 1.5 + 0.3,
      speed: Math.random() * 30 + 10,
      alpha: Math.random() * 0.6 + 0.2,
    });
  }
}

// ── Player ────────────────────────────────────────────────────────
function resetPlayer() {
  player = {
    x:            canvas.width / 2,
    y:            canvas.height - 80,
    w:            36,
    h:            40,
    speed:        260,
    invincible:   0,
    shootCooldown:0,
    shootRate:    0.22,
  };
}

// ── Bullets ───────────────────────────────────────────────────────
function spawnBullet() {
  bullets.push({
    x: player.x,
    y: player.y - player.h / 2,
    w: 5, h: 14,
    speed: 520,
    fromPlayer: true,
  });
}

function spawnEnemyBullet(e) {
  const angle = Math.atan2(player.y - e.y, player.x - e.x);
  const spd   = 150 + level * 18;
  bullets.push({
    x: e.x, y: e.y + e.h / 2,
    w: 5, h: 12,
    vx: Math.cos(angle) * spd,
    vy: Math.sin(angle) * spd,
    speed: spd,
    fromPlayer: false,
  });
}

// ── Enemies ───────────────────────────────────────────────────────
const ENEMY_TYPES = [
  { color: '#ff4466', hp: 1, score: 10, w: 30, h: 28, speed: 70,  shootChance: 0.003 },
  { color: '#ffaa00', hp: 2, score: 25, w: 36, h: 32, speed: 55,  shootChance: 0.005 },
  { color: '#cc44ff', hp: 3, score: 50, w: 44, h: 38, speed: 40,  shootChance: 0.008 },
];

function spawnEnemy() {
  const typeIdx = Math.min(Math.floor(Math.random() * (1 + Math.floor(level / 3))), 2);
  const t = ENEMY_TYPES[typeIdx];
  const margin = t.w;
  enemies.push({
    x:          margin + Math.random() * (canvas.width - margin * 2),
    y:          -t.h,
    w:          t.w,
    h:          t.h,
    hp:         t.hp,
    maxHp:      t.hp,
    speed:      t.speed + level * 5,
    color:      t.color,
    score:      t.score,
    shootChance:t.shootChance,
    wobble:     Math.random() * Math.PI * 2,
    wobbleAmp:  30 + Math.random() * 40,
    wobbleFreq: 1.5 + Math.random(),
  });
}

// ── Collectible Stars ─────────────────────────────────────────────
function spawnStar(x, y) {
  if (Math.random() < 0.3) {
    stars.push({ x, y, r: 8, speed: 60, value: 5 + Math.floor(level * 2) });
  }
}

// ── Particles ─────────────────────────────────────────────────────
function spawnParticles(x, y, color, count) {
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * Math.PI * 2;
    const spd   = 60 + Math.random() * 140;
    const life  = 0.5 + Math.random() * 0.4;
    particles.push({
      x, y,
      vx: Math.cos(angle) * spd,
      vy: Math.sin(angle) * spd,
      r: 2 + Math.random() * 3,
      life,
      maxLife: life,
      color,
    });
  }
}

// ── HUD ───────────────────────────────────────────────────────────
function updateHUD() {
  const scoreEl = document.getElementById('hud-score');
  const levelEl = document.getElementById('hud-level');
  const livesEl = document.getElementById('hud-lives');
  if (scoreEl) scoreEl.textContent = score;
  if (levelEl) levelEl.textContent = level;
  if (livesEl) livesEl.textContent = '❤️'.repeat(Math.max(0, lives));
}

// ── Screen Management ─────────────────────────────────────────────
function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  const el = document.getElementById(id);
  if (el) el.classList.add('active');
}

// ── Game Init / Restart ───────────────────────────────────────────
function initGame() {
  score = 0;
  level = 1;
  lives = 3;
  frameCount = 0;
  enemySpawnTimer = 0;
  autoFireTimer   = 0;
  bullets   = [];
  enemies   = [];
  stars     = [];
  particles = [];
  resetPlayer();
  updateHUD();
}

function restartGame() {
  initGame();
  gameState = 'playing';
  showScreen('screen-game');
  // Re-measure canvas now that game screen is visible
  resizeCanvas();
  resetPlayer();
}

// ── Collision ─────────────────────────────────────────────────────
function rectOverlap(ax, ay, aw, ah, bx, by, bw, bh) {
  return ax - aw / 2 < bx + bw / 2 &&
         ax + aw / 2 > bx - bw / 2 &&
         ay - ah / 2 < by + bh / 2 &&
         ay + ah / 2 > by - bh / 2;
}

function circleRect(cx, cy, cr, rx, ry, rw, rh) {
  const nearX = Math.max(rx - rw / 2, Math.min(cx, rx + rw / 2));
  const nearY = Math.max(ry - rh / 2, Math.min(cy, ry + rh / 2));
  const dx = cx - nearX, dy = cy - nearY;
  return dx * dx + dy * dy < cr * cr;
}

// ── Lose Life ─────────────────────────────────────────────────────
function loseLife() {
  lives--;
  spawnParticles(player.x, player.y, C.accent(), 20);
  if (lives <= 0) {
    gameState = 'gameover';
    showGameOver();
  } else {
    player.invincible = 2.0;
  }
}

// ── Game Over ─────────────────────────────────────────────────────
function showGameOver() {
  if (score > bestScore) {
    bestScore = score;
    try { localStorage.setItem('arcade_best', bestScore); } catch(e) {}
  }
  const goScore  = document.getElementById('go-score');
  const goBest   = document.getElementById('go-best');
  const newBestEl= document.getElementById('go-newbest');
  if (goScore)  goScore.textContent  = score;
  if (goBest)   goBest.textContent   = bestScore;
  if (newBestEl) newBestEl.style.display = (score >= bestScore && score > 0) ? 'block' : 'none';
  showScreen('screen-gameover');
}

// ── Update ────────────────────────────────────────────────────────
function update(dt) {
  frameCount++;

  // Level progression
  level = 1 + Math.floor(score / 200);
  const spawnInterval = Math.max(0.5, 2.2 - level * 0.12);

  // Player movement
  const inp = window.inputState || {};
  if (inp.left)  player.x -= player.speed * dt;
  if (inp.right) player.x += player.speed * dt;
  player.x = Math.max(player.w / 2, Math.min(canvas.width - player.w / 2, player.x));

  // Auto-fire
  if (inp.fire) {
    autoFireTimer += dt;
    if (autoFireTimer >= player.shootRate) {
      autoFireTimer = 0;
      spawnBullet();
    }
  } else {
    autoFireTimer = 0;
  }

  // Invincibility frames
  if (player.invincible > 0) player.invincible -= dt;

  // Background stars scroll
  for (const s of bgStars) {
    s.y += s.speed * dt;
    if (s.y > canvas.height) { s.y = -2; s.x = Math.random() * canvas.width; }
  }

  // Enemy spawn
  enemySpawnTimer += dt;
  if (enemySpawnTimer >= spawnInterval) {
    enemySpawnTimer = 0;
    spawnEnemy();
    if (level >= 5 && Math.random() < 0.3) spawnEnemy();
  }

  // Update enemies
  for (let i = enemies.length - 1; i >= 0; i--) {
    const e = enemies[i];
    e.wobble += e.wobbleFreq * dt;
    e.x += Math.sin(e.wobble) * e.wobbleAmp * dt;
    e.y += e.speed * dt;

    if (Math.random() < e.shootChance * (1 + level * 0.2)) {
      spawnEnemyBullet(e);
    }

    if (e.y - e.h / 2 > canvas.height) {
      enemies.splice(i, 1);
      loseLife();
      if (gameState !== 'playing') return;
      continue;
    }

    if (player.invincible <= 0 &&
        rectOverlap(player.x, player.y, player.w, player.h, e.x, e.y, e.w, e.h)) {
      spawnParticles(e.x, e.y, e.color, 12);
      enemies.splice(i, 1);
      loseLife();
      if (gameState !== 'playing') return;
    }
  }

  // Update bullets
  for (let i = bullets.length - 1; i >= 0; i--) {
    const b = bullets[i];
    if (b.fromPlayer) {
      b.y -= b.speed * dt;
    } else {
      b.x += (b.vx || 0) * dt;
      b.y += (b.vy !== undefined ? b.vy : b.speed) * dt;
    }

    if (b.y < -20 || b.y > canvas.height + 20 || b.x < -20 || b.x > canvas.width + 20) {
      bullets.splice(i, 1);
      continue;
    }

    if (b.fromPlayer) {
      let hit = false;
      for (let j = enemies.length - 1; j >= 0; j--) {
        const e = enemies[j];
        if (rectOverlap(b.x, b.y, b.w, b.h, e.x, e.y, e.w, e.h)) {
          e.hp--;
          spawnParticles(b.x, b.y, C.primary(), 5);
          hit = true;
          if (e.hp <= 0) {
            score += e.score;
            spawnParticles(e.x, e.y, e.color, 16);
            spawnStar(e.x, e.y);
            enemies.splice(j, 1);
          }
          break;
        }
      }
      if (hit) { bullets.splice(i, 1); continue; }
    } else {
      if (player.invincible <= 0 &&
          rectOverlap(b.x, b.y, b.w, b.h, player.x, player.y, player.w, player.h)) {
        spawnParticles(b.x, b.y, C.accent(), 8);
        bullets.splice(i, 1);
        loseLife();
        if (gameState !== 'playing') return;
        continue;
      }
    }
  }

  // Update collectible stars
  for (let i = stars.length - 1; i >= 0; i--) {
    const s = stars[i];
    s.y += s.speed * dt;
    if (circleRect(s.x, s.y, s.r, player.x, player.y, player.w, player.h)) {
      score += s.value;
      spawnParticles(s.x, s.y, '#ffee44', 6);
      stars.splice(i, 1);
      continue;
    }
    if (s.y > canvas.height + 20) stars.splice(i, 1);
  }

  // Update particles
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.vx *= 0.94;
    p.vy *= 0.94;
    p.life -= dt;
    if (p.life <= 0) particles.splice(i, 1);
  }

  // Best score live
  if (score > bestScore) {
    bestScore = score;
    try { localStorage.setItem('arcade_best', bestScore); } catch(e) {}
  }

  updateHUD();
}

// ── Draw ──────────────────────────────────────────────────────────
function draw() {
  const W = canvas.width;
  const H = canvas.height;

  // Background
  ctx.fillStyle = C.bg();
  ctx.fillRect(0, 0, W, H);

  // BG stars
  for (const s of bgStars) {
    ctx.globalAlpha = s.alpha;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  // Collectible stars
  for (const s of stars) drawStarShape(s.x, s.y, s.r, '#ffee44');

  // Enemies
  for (const e of enemies) drawEnemy(e);

  // Player
  drawPlayer();

  // Bullets
  for (const b of bullets) {
    if (b.fromPlayer) {
      ctx.fillStyle = C.primary();
      ctx.shadowColor = C.primary();
      ctx.shadowBlur = 8;
    } else {
      ctx.fillStyle = C.accent();
      ctx.shadowColor = C.accent();
      ctx.shadowBlur = 6;
    }
    ctx.beginPath();
    ctx.roundRect(b.x - b.w / 2, b.y - b.h / 2, b.w, b.h, 3);
    ctx.fill();
    ctx.shadowBlur = 0;
  }

  // Particles
  for (const p of particles) {
    ctx.globalAlpha = Math.max(0, p.life / p.maxLife);
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  // Invincible flash
  if (player.invincible > 0 && Math.floor(player.invincible * 10) % 2 === 0) {
    ctx.globalAlpha = 0.25;
    ctx.fillStyle = C.accent();
    ctx.fillRect(0, 0, W, H);
    ctx.globalAlpha = 1;
  }
}

// ── Draw helpers ──────────────────────────────────────────────────
function drawPlayer() {
  if (player.invincible > 0 && Math.floor(player.invincible * 8) % 2 === 0) return;

  const x = player.x, y = player.y;
  const w = player.w, h = player.h;

  ctx.save();
  ctx.translate(x, y);
  ctx.shadowColor = C.primary();
  ctx.shadowBlur = 16;

  // Hull
  ctx.fillStyle = C.primary();
  ctx.beginPath();
  ctx.moveTo(0, -h / 2);
  ctx.lineTo(w / 2, h / 2);
  ctx.lineTo(w * 0.15, h * 0.25);
  ctx.lineTo(-w * 0.15, h * 0.25);
  ctx.lineTo(-w / 2, h / 2);
  ctx.closePath();
  ctx.fill();

  // Cockpit
  ctx.fillStyle = C.accent();
  ctx.beginPath();
  ctx.ellipse(0, -h * 0.05, w * 0.15, h * 0.22, 0, 0, Math.PI * 2);
  ctx.fill();

  // Engine flame
  const flicker = 0.7 + 0.3 * Math.sin(frameCount * 0.4);
  ctx.fillStyle = C.accent();
  ctx.shadowColor = C.accent();
  ctx.shadowBlur = 10;
  ctx.beginPath();
  ctx.moveTo(-w * 0.25, h * 0.25);
  ctx.lineTo(0, h * 0.25 + 16 * flicker);
  ctx.lineTo(w * 0.25, h * 0.25);
  ctx.closePath();
  ctx.fill();

  ctx.shadowBlur = 0;
  ctx.restore();
}

function drawEnemy(e) {
  ctx.save();
  ctx.translate(e.x, e.y);

  // HP bar
  if (e.maxHp > 1) {
    const barW = e.w * 1.1, barH = 4;
    const bx = -barW / 2, by = -e.h / 2 - 8;
    ctx.fillStyle = '#333';
    ctx.fillRect(bx, by, barW, barH);
    ctx.fillStyle = e.color;
    ctx.fillRect(bx, by, barW * (e.hp / e.maxHp), barH);
  }

  ctx.shadowColor = e.color;
  ctx.shadowBlur = 12;
  ctx.fillStyle = e.color;
  ctx.beginPath();
  ctx.moveTo(0, e.h / 2);
  ctx.lineTo(e.w / 2, -e.h / 2);
  ctx.lineTo(-e.w / 2, -e.h / 2);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = '#fff';
  ctx.shadowBlur = 0;
  ctx.beginPath();
  ctx.arc(0, 0, e.w * 0.12, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}

function drawStarShape(cx, cy, r, color) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.fillStyle = color;
  ctx.shadowColor = color;
  ctx.shadowBlur = 10;
  ctx.beginPath();
  for (let i = 0; i < 5; i++) {
    const outerA = (i * 4 * Math.PI) / 5 - Math.PI / 2;
    const innerA = outerA + (2 * Math.PI) / 10;
    if (i === 0) ctx.moveTo(Math.cos(outerA) * r, Math.sin(outerA) * r);
    else         ctx.lineTo(Math.cos(outerA) * r, Math.sin(outerA) * r);
    ctx.lineTo(Math.cos(innerA) * r * 0.45, Math.sin(innerA) * r * 0.45);
  }
  ctx.closePath();
  ctx.fill();
  ctx.shadowBlur = 0;
  ctx.restore();
}

// ── Menu animated background ───────────────────────────────────────
function drawMenuBg(dt) {
  const W = canvas.width, H = canvas.height;
  ctx.fillStyle = C.bg();
  ctx.fillRect(0, 0, W, H);
  ctx.globalAlpha = 0.5;
  for (const s of bgStars) {
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
    s.y += s.speed * dt;
    if (s.y > H) { s.y = 0; s.x = Math.random() * W; }
  }
  ctx.globalAlpha = 1;
}

// ── Button Wiring ─────────────────────────────────────────────────
function wireButtons() {
  const btnStart   = document.getElementById('btn-start');
  const btnRestart = document.getElementById('btn-restart');
  const btnMenu    = document.getElementById('btn-menu');

  if (btnStart) {
    btnStart.addEventListener('pointerdown', e => { e.preventDefault(); restartGame(); });
  }
  if (btnRestart) {
    btnRestart.addEventListener('pointerdown', e => { e.preventDefault(); restartGame(); });
  }
  if (btnMenu) {
    btnMenu.addEventListener('pointerdown', e => {
      e.preventDefault();
      gameState = 'menu';
      showScreen('screen-menu');
      const menuHi = document.getElementById('menu-hiscore');
      if (menuHi) menuHi.textContent = bestScore;
    });
  }
}

// ── GAME LOOP ─────────────────────────────────────────────────────
let lastTime = 0;

function gameLoop(ts) {
  const dt = Math.min((ts - lastTime) / 1000, 0.05);
  lastTime = ts;

  if (gameState === 'playing') {
    update(dt);
    draw();
  } else if (gameState === 'menu') {
    drawMenuBg(dt);
  }
  // gameover: nothing drawn on canvas (overlay screen shown)

  requestAnimationFrame(gameLoop);
}

// ── Bootstrap ─────────────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
  resizeCanvas();
  initBgStars();
  resetPlayer();
  wireButtons();

  // Show menu
  gameState = 'menu';
  showScreen('screen-menu');
  const menuHi = document.getElementById('menu-hiscore');
  if (menuHi) menuHi.textContent = bestScore;

  requestAnimationFrame(gameLoop);
});

/* ── input.js ── shared input state ── */
window.inputState = { left: false, right: false, fire: false };

document.addEventListener('DOMContentLoaded', () => {
  const btnLeft  = document.getElementById('btn-left');
  const btnRight = document.getElementById('btn-right');
  const btnFire  = document.getElementById('btn-fire');

  function bindHold(el, key) {
    if (!el) return;
    el.addEventListener('pointerdown',  e => { e.preventDefault(); window.inputState[key] = true;  });
    el.addEventListener('pointerup',    e => { e.preventDefault(); window.inputState[key] = false; });
    el.addEventListener('pointerleave', e => { window.inputState[key] = false; });
    el.addEventListener('pointercancel',e => { window.inputState[key] = false; });
  }

  bindHold(btnLeft,  'left');
  bindHold(btnRight, 'right');
  bindHold(btnFire,  'fire');

  // Keyboard support
  document.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft'  || e.key === 'a') window.inputState.left  = true;
    if (e.key === 'ArrowRight' || e.key === 'd') window.inputState.right = true;
    if (e.key === ' ' || e.key === 'z')          window.inputState.fire  = true;
  });
  document.addEventListener('keyup', e => {
    if (e.key === 'ArrowLeft'  || e.key === 'a') window.inputState.left  = false;
    if (e.key === 'ArrowRight' || e.key === 'd') window.inputState.right = false;
    if (e.key === ' ' || e.key === 'z')          window.inputState.fire  = false;
  });
});
